from __future__ import annotations

from datetime import UTC, datetime
from pathlib import Path

import numpy as np
import pandas as pd

from churnsense.data.loading import DatasetProvenance, file_sha256, write_provenance
from churnsense.data.schema import INTERNET_ADDON_FEATURES, NO_INTERNET, NO_PHONE

FIXTURE_NOTICE = (
    "SYNTHETIC DEVELOPMENT FIXTURE. Generated by churnsense.data.fixture for tests and offline "
    "development. It does not describe real customers and metrics computed on it are not "
    "meaningful evidence of model quality."
)

CONTRACT_EFFECT = {"Month-to-month": 1.1, "One year": -0.4, "Two year": -1.4}
INTERNET_EFFECT = {"Fiber optic": 0.6, "DSL": 0.0, "No": -0.7}
PAYMENT_EFFECT = {
    "Electronic check": 0.5,
    "Mailed check": 0.0,
    "Bank transfer (automatic)": -0.2,
    "Credit card (automatic)": -0.2,
}


def _choice(rng: np.random.Generator, options: list[str], weights: list[float], size: int):
    return rng.choice(options, size=size, p=np.asarray(weights) / np.sum(weights))


def _yes_no(rng: np.random.Generator, probability_yes: float, size: int) -> np.ndarray:
    return np.where(rng.random(size) < probability_yes, "Yes", "No")


def generate_synthetic_customers(rows: int = 1500, seed: int = 7) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    contract = _choice(rng, list(CONTRACT_EFFECT), [0.55, 0.21, 0.24], rows)
    internet = _choice(rng, list(INTERNET_EFFECT), [0.34, 0.44, 0.22], rows)
    payment = _choice(rng, list(PAYMENT_EFFECT), [0.34, 0.23, 0.22, 0.21], rows)
    phone = _yes_no(rng, 0.9, rows)
    tenure_scale = np.select([contract == "Two year", contract == "One year"], [52, 36], 14)
    tenure = np.clip(rng.exponential(tenure_scale), 0, 72).round().astype(int)

    frame = pd.DataFrame({
        "customerID": [f"SYN-{index:05d}" for index in range(rows)],
        "gender": _choice(rng, ["Female", "Male"], [0.5, 0.5], rows),
        "SeniorCitizen": np.where(rng.random(rows) < 0.16, "1", "0"),
        "Partner": _yes_no(rng, 0.48, rows),
        "Dependents": _yes_no(rng, 0.3, rows),
        "tenure": tenure,
        "PhoneService": phone,
        "MultipleLines": np.where(phone == "No", NO_PHONE, _yes_no(rng, 0.47, rows)),
        "InternetService": internet,
        "Contract": contract,
        "PaperlessBilling": _yes_no(rng, 0.59, rows),
        "PaymentMethod": payment,
    })
    for addon in INTERNET_ADDON_FEATURES:
        frame[addon] = np.where(internet == "No", NO_INTERNET, _yes_no(rng, 0.4, rows))

    base_charge = np.select([internet == "Fiber optic", internet == "DSL"], [70.0, 45.0], 20.0)
    addon_count = sum((frame[addon] == "Yes").astype(int) for addon in INTERNET_ADDON_FEATURES)
    monthly = base_charge + 5.0 * addon_count + rng.normal(0, 4, rows)
    monthly = np.clip(monthly, 18.0, 120.0).round(2)
    frame["MonthlyCharges"] = monthly
    total = (monthly * tenure * rng.uniform(0.95, 1.05, rows)).round(2)
    frame["TotalCharges"] = np.where(tenure == 0, "", total.astype(str))

    logit = (
        -1.9
        + pd.Series(contract).map(CONTRACT_EFFECT).to_numpy()
        + pd.Series(internet).map(INTERNET_EFFECT).to_numpy()
        + pd.Series(payment).map(PAYMENT_EFFECT).to_numpy()
        - 0.035 * tenure
        + 0.012 * (monthly - 65)
        - 0.35 * (frame["TechSupport"] == "Yes").to_numpy()
        - 0.3 * (frame["OnlineSecurity"] == "Yes").to_numpy()
        + rng.normal(0, 0.5, rows)
    )
    probability = 1.0 / (1.0 + np.exp(-logit))
    frame["Churn"] = np.where(rng.random(rows) < probability, "Yes", "No")
    return frame


def write_synthetic_fixture(destination: Path, rows: int = 1500, seed: int = 7) -> DatasetProvenance:
    destination.parent.mkdir(parents=True, exist_ok=True)
    generate_synthetic_customers(rows=rows, seed=seed).to_csv(destination, index=False)
    provenance = DatasetProvenance(
        name="ChurnSense synthetic development fixture",
        source_url=None,
        repository=None,
        license="Generated data, no third-party license",
        sha256=file_sha256(destination),
        rows=rows,
        retrieved_at=datetime.now(UTC).isoformat(),
        synthetic=True,
        notes=f"{FIXTURE_NOTICE} Generator seed={seed}.",
    )
    write_provenance(destination, provenance)
    return provenance
